package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for FastMath.cosh(double x).
 * Designed to maximize branch and line coverage.
 */
public class FastMath_cosh_TriageGen2Test {

    private static final double DELTA = 1e-14;

    @Test
    public void testCoshNaN() {
        double nan = Double.NaN;
        assertEquals(nan, FastMath.cosh(nan), 0.0);
    }

    @Test
    public void testCoshZero() {
        // cosh(0) = (exp(0) + exp(0))/2 = 1
        assertEquals(1.0, FastMath.cosh(0.0), DELTA);
        assertEquals(1.0, FastMath.cosh(-0.0), DELTA);
    }

    @Test
    public void testCoshPositiveSmall() {
        // Test values within the [-20, 20] range where high precision path is taken
        // cosh(1) = (e^1 + e^-1)/2 approx 1.5430806348152437
        assertEquals(1.5430806348152437, FastMath.cosh(1.0), DELTA);
    }

    @Test
    public void testCoshNegativeSmall() {
        // cosh(-x) = cosh(x)
        assertEquals(1.5430806348152437, FastMath.cosh(-1.0), DELTA);
    }

    @Test
    public void testCoshLargePositive() {
        // Test x > 20 branch
        // cosh(25) approx 0.5 * exp(25)
        double x = 25.0;
        double expected = 0.5 * Math.exp(x);
        assertEquals(expected, FastMath.cosh(x), DELTA);
    }

    @Test
    public void testCoshLargeNegative() {
        // Test x < -20 branch
        // cosh(-25) approx 0.5 * exp(25)
        double x = -25.0;
        double expected = 0.5 * Math.exp(-x);
        assertEquals(expected, FastMath.cosh(x), DELTA);
    }

    @Test
    public void testCoshBoundaryPositive() {
        // Test boundary near 20
        assertEquals(0.5 * Math.exp(20.0), FastMath.cosh(20.0), DELTA);
    }

    @Test
    public void testCoshBoundaryNegative() {
        // Test boundary near -20
        assertEquals(0.5 * Math.exp(20.0), FastMath.cosh(-20.0), DELTA);
    }

    @Test
    public void testCoshVeryLarge() {
        // Test overflow potential
        double x = 700.0;
        double expected = 0.5 * Math.exp(x);
        assertEquals(expected, FastMath.cosh(x), DELTA);
    }

    @Test
    public void testCoshInfinity() {
        assertEquals(Double.POSITIVE_INFINITY, FastMath.cosh(Double.POSITIVE_INFINITY), 0.0);
        assertEquals(Double.POSITIVE_INFINITY, FastMath.cosh(Double.NEGATIVE_INFINITY), 0.0);
    }
}
